from typing import List

class Solution:
    def minSizeSubarray(self, nums: List[int], target: int) -> int:
        n = len(nums)
        total = sum(nums)
        pre = [0] * n
        for t in range(1, n):
            pre[t] = pre[t - 1] + nums[t - 1]
        index_of = {pre[t]: t for t in range(n)}

        best = -1
        for i in range(n):
            v = pre[i] + target
            q, rem = divmod(v, total)
            if rem in index_of:
                j = q * n + index_of[rem]
                length = j - i
                if best == -1 or length < best:
                    best = length
        return best
