class Solution:
    def minSizeSubarray(self, nums: List[int], target: int) -> int:
        n = len(nums)
        total = sum(nums)
        full = target // total
        rem = target % total

        if rem == 0:
            return full * n

        arr = nums + nums
        best = float('inf')
        window_sum = 0
        left = 0
        for right in range(len(arr)):
            window_sum += arr[right]
            while window_sum > rem and left <= right:
                window_sum -= arr[left]
                left += 1
            if window_sum == rem:
                best = min(best, right - left + 1)

        if best == float('inf'):
            return -1
        return full * n + best
