import json
from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.one_of(st.just(1), st.integers(1, 6)))
    kind = draw(st.integers(0, 4))
    if kind == 0:
        # all-equal elements
        v = draw(st.integers(1, 10))
        nums = [v] * n
    elif kind == 1:
        # sorted ascending
        nums = sorted(draw(st.lists(st.integers(1, 10), min_size=n, max_size=n)))
    elif kind == 2:
        # reverse sorted
        nums = sorted(draw(st.lists(st.integers(1, 10), min_size=n, max_size=n)), reverse=True)
    else:
        nums = draw(st.lists(st.integers(1, 10), min_size=n, max_size=n))
    target = draw(st.integers(1, 40))
    return json.dumps(nums) + "\n" + json.dumps(target) + "\n"

def validate(inp):
    lines = inp.strip("\n").split("\n")
    if len(lines) != 2:
        return False
    try:
        nums = json.loads(lines[0])
        target = json.loads(lines[1])
    except Exception:
        return False
    if not isinstance(nums, list) or not isinstance(target, int) or isinstance(target, bool):
        return False
    if not (1 <= len(nums) <= 10**5):
        return False
    if not all(isinstance(x, int) and not isinstance(x, bool) and 1 <= x <= 10**5 for x in nums):
        return False
    if not (1 <= target <= 10**9):
        return False
    return True

def ref(inp):
    lines = inp.strip("\n").split("\n")
    nums = json.loads(lines[0])
    target = json.loads(lines[1])
    n = len(nums)
    # All elements are positive, so any subarray of length L has sum >= L.
    # Hence a valid answer has length <= target. Brute force over lengths
    # and starting positions (start mod n suffices by periodicity).
    for L in range(1, target + 1):
        for start in range(n):
            s = 0
            for k in range(L):
                s += nums[(start + k) % n]
            if s == target:
                return json.dumps(L)
    return json.dumps(-1)
